<!-- engineering-about -->
<section class="engineering-about">
    <div class="container">
        <div class="engineering-about__content">
            <div class="engineering-about__list">
                <div class="engineering-about__item fade-in-up">
                    <div class="engineering-about__title">Электрические системы с&nbsp;резервированием <br>и&nbsp;автономным питанием</div>
                </div>
                <div class="engineering-about__item fade-in-up">
                    <div class="engineering-about__title">Водоснабжение с&nbsp;контролем давления</div>
                </div>
                <div class="engineering-about__item fade-in-up">
                    <div class="engineering-about__title">Отопление с&nbsp;индивидуальной регулировкой</div>
                </div>
                <div class="engineering-about__item fade-in-up">
                    <div class="engineering-about__title">Интернет, телефония, охранные системы</div>
                </div>
                <div class="engineering-about__item fade-in-up">
                    <div class="engineering-about__title">Канализация с&nbsp;насосными станциями и&nbsp;системами очистки</div>
                </div>
            </div>
            <div class="engineering-about__image fade-in">
                <picture>
                    <source srcset="img/default.png" data-srcset="img/engineering-about/main.webp 1x, img/engineering-about/main@2x.webp 2x" type="image/webp">
                    <source srcset="img/default.png" data-srcset="img/engineering-about/main.jpg 1x, img/engineering-about/main@2x.jpg 2x" type="image/jpeg">
                    <img class="lazyload" src="img/default.png" data-srcset="img/engineering-about/main.jpg 1x, img/engineering-about/main@2x.jpg 2x" alt="img">
                </picture>
            </div>
        </div>
    </div>
</section>
